def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Количество чисел в [start, finish], оканчивающихся на s, все цифры которых не больше limit."""
    if any(int(c) > limit for c in s):
        return 0

    def upto(n: int) -> int:
        t = str(n)
        k = len(s)
        if len(t) < k:
            return 0
        rest = len(t) - k
        total = 0
        for i in range(rest):
            d = int(t[i])
            if d > limit:
                return total + (limit + 1) ** (rest - i)
            total += d * (limit + 1) ** (rest - i - 1)
        return total + (1 if t[rest:] >= s else 0)

    return upto(finish) - upto(start - 1)
